def format_paragraphs(p_list):
    return '[\n' + ',\n'.join('    ' + repr(p) for p in p_list) + '\n]'

with open('scripts/build_day35_cloud.py', 'r', encoding='utf-8') as f:
    content = f.read()

content = re.sub(r'p1_say = \[[\s\S]*?\]\n\np1_code', f'p1_say = {format_paragraphs(p1_new)}\n\np1_code', content)
content = re.sub(r'p2_say = \[[\s\S]*?\]\n\np2_code', f'p2_say = {format_paragraphs(p2_new)}\n\np2_code', content)
content = re.sub(r'p3_say = \[[\s\S]*?\]\n\np3_code', f'p3_say = {format_paragraphs(p3_new)}\n\np3_code', content)
content = re.sub(r'p4_say = \[[\s\S]*?\]\n\np4_code', f'p4_say = {format_paragraphs(p4_new)}\n\np4_code', content)
content = re.sub(r'p5_say = \[[\s\S]*?\]\n\np5_code', f'p5_say = {format_paragraphs(p5_new)}\n\np5_code', content)

with open('scripts/build_day35_cloud.py', 'w', encoding='utf-8') as f:
    f.write(content)

